	/** @param iterable<PanelOperationRecord|array<string,mixed>> $operations */
	public static function operations(iterable $operations, array $options=[]): PanelPageResult {
		$rows=[]; $records=[];
		foreach($operations as $operation){
			$record=$operation instanceof PanelOperationRecord ? $operation->jsonSerialize() : (is_array($operation) ? $operation : []);
			if($record===[]){ continue; }
			$records[]=$record;
			$id=(string)($record['id'] ?? ''); $status=(string)($record['status'] ?? 'unknown'); $percent=max(0, min(100, (int)($record['progress']['percent'] ?? $record['percent'] ?? 0)));
			$rows[]='<tr data-dp-operation-id="'.self::e($id).'">'
				.'<td data-label="Operation"><strong>'.self::e((string)($record['name'] ?? $record['type'] ?? 'Operation')).'</strong><small>'.self::e($id).'</small></td>'
				.'<td data-label="Status">'.self::badge($status, self::statusTone($status)).'</td>'
				.'<td data-label="Progress"><progress value="'.$percent.'" max="100" aria-label="'.self::e($percent.' percent complete').'">'.$percent.'%</progress><small>'.self::e((string)($record['progress_message'] ?? '')).'</small></td>'
				.'<td data-label="Attempts">'.self::e((string)($record['attempt'] ?? 0)).' / '.self::e((string)($record['max_attempts'] ?? 1)).'</td>'
				.'<td data-label="Updated"><time>'.self::e((string)($record['updated_at'] ?? '')).'</time></td>'
				.'<td data-label="Actions"><div class="dp-panel-actions">'.self::operationActions($record, $options).'</div></td>'
				.'</tr>';
		}
		$body='<section aria-labelledby="dp-operations-heading">'.self::sectionHeading('dp-operations-heading', 'Operations', count($records).' total')
			.($rows===[] ? self::empty('No operations yet.', 'Queued imports, exports, bulk actions, and media work will appear here.') : '<div class="dp-panel-table-shell"><table class="dp-panel-table"><thead><tr><th>Operation</th><th>Status</th><th>Progress</th><th>Attempts</th><th>Updated</th><th>Actions</th></tr></thead><tbody>'.implode('', $rows).'</tbody></table></div>')
			.'</section>';
		return self::page('Operations center', 'Persistent background work, progress, failures, artifacts, and recovery.', $body, ['operations'=>$records, 'surface'=>'operations_center'], $options);
	}

