			.'<label><span>Theme</span><select name="theme">'.self::options(['default'=>'Default','glass'=>'Glass','flat_minimal'=>'Flat minimal','brutalist'=>'Brutalist'],(string)($appearance['theme'] ?? 'default')).'</select></label>'
