			.'<label><span>Direction</span><select name="direction">'.self::options(['auto'=>'Automatic','ltr'=>'Left to right','rtl'=>'Right to left'],(string)($appearance['direction'] ?? 'auto')).'</select></label>'
			.'<button type="submit" class="dp-panel-button">Save appearance</button></form>';
