				if(!is_array($view)){ continue; }
				$delete='<form method="post" action="'.self::e($actionUrl).'" data-dp-panel-ajax><input type="hidden" name="operation" value="delete_table_view"><input type="hidden" name="resource" value="'.self::e((string)$resource).'"><input type="hidden" name="name" value="'.self::e((string)$name).'"><button type="submit" class="dp-panel-button">Delete</button></form>';
				$viewRows[]='<tr><td data-label="Resource">'.self::e(self::humanize((string)$resource)).'</td><td data-label="View"><strong>'.self::e(self::humanize((string)$name)).'</strong></td><td data-label="Presentation">'.self::e(self::humanize((string)($view['presentation'] ?? 'table'))).'</td><td data-label="Updated"><time>'.self::e((string)($view['updated_at'] ?? '')).'</time></td><td data-label="Actions">'.$delete.'</td></tr>';
