		};
		$body='<section aria-labelledby="dp-preferences-appearance">'.self::sectionHeading('dp-preferences-appearance','Appearance and device defaults','Revision '.(int)($manifest['revision'] ?? 0)).$appearanceForm.'</section>'
			.'<section aria-labelledby="dp-preferences-views">'.self::sectionHeading('dp-preferences-views','Saved table views',count($viewRows).' views').($viewRows!==[]?'<div class="dp-panel-table-shell"><table class="dp-panel-table"><thead><tr><th>Resource</th><th>View</th><th>Presentation</th><th>Updated</th><th>Actions</th></tr></thead><tbody>'.implode('',$viewRows).'</tbody></table></div>':self::empty('No saved views.','Named filters, sorts, groups, columns, and presentations will appear here.')).'</section>'
			.'<section aria-labelledby="dp-preferences-pinned">'.self::sectionHeading('dp-preferences-pinned','Pinned workspace items',count((array)($resolved['pinned'] ?? [])).' pinned').$list((array)($resolved['pinned'] ?? []),'Nothing pinned.','Pin frequently used records and pages for fast access.').'</section>'
