	public static function collaboration(PanelCollaborationManager $manager, array $options=[]): PanelPageResult {
		$actionUrl=self::url((string)($options['action_url'] ?? ''));
		$subjectType=isset($options['subject_type']) ? (string)$options['subject_type'] : null;
		$subjectId=$options['subject_id'] ?? null;
		$status=isset($options['status']) ? (string)$options['status'] : null;
		$threads=$manager->threads($subjectType,$subjectId,$status); $items=[];
		foreach($threads as $thread){
			$id=(string)($thread['id'] ?? ''); $commentItems=[];
			foreach($manager->comments($id) as $comment){
				$commentItems[]='<li><header><strong>'.self::e((string)($comment['actor'] ?? 'Unknown')).'</strong><time>'.self::e((string)($comment['created_at'] ?? '')).'</time></header><p>'.self::e((string)($comment['body'] ?? '')).'</p></li>';
			}
			$items[]='<article class="dp-panel-card dp-panel-thread" data-dp-thread-id="'.self::e($id).'"><header><div><strong>'.self::e((string)($thread['title'] ?? 'Discussion')).'</strong><small>'.self::e((string)($thread['subject_type'] ?? '')).' / '.self::e((string)($thread['subject_id'] ?? '')).'</small></div>'.self::badge((string)($thread['status'] ?? 'open'),self::statusTone((string)($thread['status'] ?? 'open'))).'</header><ol class="dp-panel-comment-list">'.implode('',$commentItems).'</ol><form method="post" action="'.self::e($actionUrl).'" data-dp-panel-ajax><input type="hidden" name="operation" value="comment"><input type="hidden" name="thread_id" value="'.self::e($id).'"><label><span>Add comment</span><textarea name="body" rows="3" required></textarea></label><button type="submit" class="dp-panel-button">Post comment</button></form></article>';
		}
		$create='<form method="post" action="'.self::e($actionUrl).'" class="dp-panel-commandbar dp-panel-form-grid" data-dp-panel-ajax><input type="hidden" name="operation" value="create_thread"><label><span>Subject type</span><input name="subject_type" value="'.self::e((string)($subjectType ?? '')).'" required></label><label><span>Subject id</span><input name="subject_id" value="'.self::e((string)($subjectId ?? '')).'" required></label><label><span>Thread title</span><input name="title" required></label><button type="submit" class="dp-panel-button">Start thread</button></form>';
		$subscriptions=$manager->subscriptions(isset($options['user_id'])?(string)$options['user_id']:null); $subscriptionRows=[];
		foreach($subscriptions as $subscription){ $subscriptionRows[]='<tr><td data-label="Topic">'.self::e((string)($subscription['topic'] ?? '')).'</td><td data-label="User">'.self::e((string)($subscription['user_id'] ?? '')).'</td><td data-label="Channels">'.self::e(implode(', ',(array)($subscription['channels'] ?? []))).'</td><td data-label="Mode">'.self::e((string)($subscription['mode'] ?? 'immediate')).'</td></tr>'; }
		$manifest=$manager->manifest(); $chain=is_array($manifest['receipt_chain'] ?? null)?$manifest['receipt_chain']:[];
		$body='<section aria-labelledby="dp-collaboration-overview">'.self::sectionHeading('dp-collaboration-overview','Collaboration activity',count($threads).' threads').'<dl class="dp-panel-infolist"><div><dt>Comments</dt><dd>'.self::e((string)($manifest['counts']['comments'] ?? 0)).'</dd></div><div><dt>Presence</dt><dd>'.self::e((string)($manifest['counts']['presence'] ?? 0)).'</dd></div><div><dt>Receipt chain</dt><dd>'.self::badge(($chain['valid'] ?? false)?'Verified':'Attention',($chain['valid'] ?? false)?'success':'danger').'</dd></div><div><dt>Cursor</dt><dd>'.self::e((string)($manifest['cursor'] ?? 0)).'</dd></div></dl>'.$create.'<div class="dp-panel-collection" data-dp-display="grid">'.($items!==[]?implode('',$items):self::empty('No discussion threads.','Start a contextual thread for a record, assignment, or review.')).'</div></section>'
			.'<section aria-labelledby="dp-collaboration-subscriptions">'.self::sectionHeading('dp-collaboration-subscriptions','Subscriptions',count($subscriptionRows).' subscriptions').($subscriptionRows!==[]?'<div class="dp-panel-table-shell"><table class="dp-panel-table"><thead><tr><th>Topic</th><th>User</th><th>Channels</th><th>Mode</th></tr></thead><tbody>'.implode('',$subscriptionRows).'</tbody></table></div>':self::empty('No subscriptions.','Watchers and notification subscriptions will appear here.')).'</section>';
		return self::page('Collaboration workspace','Threads, comments, mentions, assignments, watchers, presence, typing, and immutable receipts.',$body,['collaboration'=>$manifest,'threads'=>$threads,'subscriptions'=>$subscriptions,'surface'=>'collaboration_workspace'],$options);
	}

	public static function security(array $reports, array $options=[]): PanelPageResult {
		$sections=[]; foreach($reports as $name=>$report){ $payload=$report instanceof \JsonSerializable ? (array)$report->jsonSerialize() : (is_array($report)?$report:['value'=>$report]); $passed=($payload['passed'] ?? $payload['allowed'] ?? $payload['verified'] ?? true)!==false; $sections[]='<section aria-labelledby="dp-security-'.self::e((string)$name).'"><header><h2 id="dp-security-'.self::e((string)$name).'">'.self::e(self::humanize((string)$name)).'</h2>'.self::badge($passed?'Pass':'Attention',$passed?'success':'danger').'</header><pre class="dp-panel-code"><code>'.self::e((string)json_encode($payload, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)).'</code></pre></section>'; }
		return self::page('Security console', 'Permissions, MFA, sessions, impersonation, tenant isolation, and audit evidence.', implode('', $sections), ['reports'=>$reports, 'surface'=>'security_console'], $options);
	}

	public static function authentication(PanelAuthenticationManager $manager,string|int $userId,array $options=[],?PanelAuthenticationAccess $access=null):PanelPageResult{
		$auth=$manager->scoped($access??PanelAuthenticationAccess::self($userId));$userId=$auth->targetUserId();$factors=$auth->factors();$devices=array_map(static fn(PanelTrustedDevice $device):array=>$device->jsonSerialize(),$auth->devices());$sessions=array_map(static fn(PanelAuthenticationSession $session):array=>$session->jsonSerialize(),$auth->sessions());$actionUrl=(string)($options['action_url']??'');$target=['user_id'=>$userId];
		$factorItems=[];foreach($factors as$factor){$factorItems[]='<article class="dp-panel-card"><header><div><strong>'.self::e((string)$factor['label']).'</strong><small>'.self::e((string)$factor['issuer']).'</small></div>'.self::badge(($factor['enabled']??false)?'Enabled':'Pending',($factor['enabled']??false)?'success':'info').'</header><p>'.self::e((string)$factor['recovery_codes_remaining']).' recovery codes remain.</p><div class="dp-panel-actions">'.self::postButton($actionUrl,(string)$factor['id'],'operation','disable_totp','Disable',$target).'</div></article>';}
		$deviceItems=[];foreach($devices as$device){$deviceItems[]='<article class="dp-panel-card"><header><div><strong>'.self::e((string)$device['label']).'</strong><small>Last seen '.self::e((string)$device['last_seen_at']).'</small></div>'.self::badge(($device['active']??false)?'Trusted':'Revoked',($device['active']??false)?'success':'neutral').'</header><div class="dp-panel-actions">'.(($device['active']??false)?self::postButton($actionUrl,(string)$device['id'],'operation','revoke_device','Revoke device',$target):'').'</div></article>';}
		$sessionRows=[];foreach($sessions as$session){$sessionRows[]='<tr><td data-label="Session"><code>'.self::e((string)$session['id']).'</code></td><td data-label="Device">'.self::e((string)($session['device_id']??'Unbound')).'</td><td data-label="Authentication">Level '.self::e((string)$session['authentication_level']).'</td><td data-label="Status">'.self::badge(($session['active']??false)?'Active':'Revoked',($session['active']??false)?'success':'neutral').'</td><td data-label="Actions"><div class="dp-panel-actions">'.(($session['active']??false)?self::postButton($actionUrl,(string)$session['id'],'operation','revoke_session','Revoke',$target):'').'</div></td></tr>';}
		$body='<section aria-labelledby="dp-auth-factors">'.self::sectionHeading('dp-auth-factors','Multi-factor authentication',count($factors).' factors').'<div class="dp-panel-actions">'.self::postButton($actionUrl,(string)$userId,'operation','provision_totp','Add authenticator',$target).'</div><div class="dp-panel-collection" data-dp-display="grid">'.($factorItems?implode('',$factorItems):self::empty('No authenticator configured.','Add a TOTP authenticator to protect sensitive operations.')).'</div></section>'
			.'<section aria-labelledby="dp-auth-devices">'.self::sectionHeading('dp-auth-devices','Trusted devices',count($devices).' devices').'<div class="dp-panel-collection" data-dp-display="grid">'.($deviceItems?implode('',$deviceItems):self::empty('No trusted devices.','Trusted devices will appear after successful verification.')).'</div></section>'
			.'<section aria-labelledby="dp-auth-sessions">'.self::sectionHeading('dp-auth-sessions','Sessions',count($sessions).' sessions').($sessionRows?'<div class="dp-panel-table-shell"><table class="dp-panel-table"><thead><tr><th>Session</th><th>Device</th><th>Authentication</th><th>Status</th><th>Actions</th></tr></thead><tbody>'.implode('',$sessionRows).'</tbody></table></div>':self::empty('No sessions.','Active and revoked sessions will appear here.')).'</section>';
		return self::page('Authentication and sessions','MFA, recovery, trusted devices, step-up challenges, and revocation.',$body,['authentication'=>$manager->jsonSerialize(),'authentication_access'=>$auth->access()->jsonSerialize(),'factors'=>$factors,'devices'=>$devices,'sessions'=>$sessions,'surface'=>'authentication'],$options);
	}

	public static function authenticationEnrollment(PanelTotpEnrollment $enrollment,array $options=[]):PanelPageResult{
		$codes=array_map(static fn(string $code):string=>'<li><code>'.self::e($code).'</code></li>',$enrollment->recoveryCodes());$target=isset($options['user_id'])?'<input type="hidden" name="user_id" value="'.self::e((string)$options['user_id']).'">':'';$body='<section aria-labelledby="dp-enroll-heading">'.self::sectionHeading('dp-enroll-heading','Set up authenticator','One-time material').'<div class="dp-panel-card"><p>Scan or enter this provisioning value in your authenticator, then confirm a generated code.</p><label><span>Provisioning URI</span><textarea readonly rows="4">'.self::e($enrollment->provisioningUri()).'</textarea></label><label><span>Secret</span><input readonly value="'.self::e($enrollment->secret()).'"></label><h3>Recovery codes</h3><p>Store these codes now. They cannot be displayed again.</p><ul class="dp-panel-recovery-codes">'.implode('',$codes).'</ul><form method="post" action="'.self::e(self::url((string)($options['action_url']??''))).'" data-dp-panel-ajax>'.$target.'<input type="hidden" name="operation" value="confirm_totp"><input type="hidden" name="id" value="'.self::e($enrollment->factorId()).'"><label><span>Authentication code</span><input name="code" inputmode="numeric" autocomplete="one-time-code" required></label><button type="submit" class="dp-panel-button">Confirm authenticator</button></form></div></section>';
		return self::page('Authenticator enrollment','Provisioning material is shown exactly once.',$body,['enrollment'=>$enrollment->jsonSerialize(),'surface'=>'authentication_enrollment'],$options);
	}

	/** @param array<string,mixed> $discovery */
	public static function packages(PanelPackageRegistryCatalog $catalog,array $discovery,array $options=[]):PanelPageResult{
		$manifest=$catalog->toArray();
		$filters=is_array($discovery['filters']??null)?$discovery['filters']:[];
		$facets=is_array($discovery['facets']??null)?$discovery['facets']:[];
		$base=self::url((string)($options['base_url']??$options['url']??''));
		$query=(string)($discovery['query']??'');
		$limit=max(1,min(100,(int)($discovery['limit']??$options['limit']??24)));
		$fieldLabels=['status'=>'Status','type'=>'Type','publisher'=>'Publisher','tag'=>'Tag','category'=>'Category','capability'=>'Capability'];
		$facetNames=['status'=>'status','type'=>'type','publisher'=>'publisher','tag'=>'tags','category'=>'categories','capability'=>'provides'];
		$fields=[];
		foreach($fieldLabels as$field=>$label){
			$selected=is_array($filters[$field]??null)?$filters[$field]:[];
			$values=is_array($facets[$facetNames[$field]]??null)?$facets[$facetNames[$field]]:[];
			foreach($selected as$value){if(is_string($value)&&$value!==''){$values[$value]=$values[$value]??0;}}
			ksort($values,SORT_STRING);
			$optionsHtml='<option value="">All '.self::e(strtolower($label)).'</option>';
			foreach($values as$value=>$count){
				if(!is_string($value)||$value===''){continue;}
				$optionsHtml.='<option value="'.self::e($value).'"'.(in_array($value,$selected,true)?' selected':'').'>'.self::e(self::humanize($value)).' ('.(int)$count.')</option>';
			}
			$fields[]='<label><span>'.self::e($label).'</span><select name="'.self::e($field).'">'.$optionsHtml.'</select></label>';
		}
		$toggles=[];
		foreach(['include_yanked'=>'Yanked','include_revoked'=>'Revoked','include_blocked'=>'Blocked publishers','all_versions'=>'All versions']as$name=>$label){
			$toggles[]='<label><input type="checkbox" name="'.self::e($name).'" value="1"'.(($filters[$name]??false)===true?' checked':'').'><span>'.self::e($label).'</span></label>';
		}
		$search='<form method="get" action="'.self::e($base).'" class="dp-panel-commandbar dp-package-catalog-filter" role="search">'
			.'<label class="dp-package-catalog-query"><span>Find packages</span><input type="search" name="q" value="'.self::e($query).'" placeholder="Name, capability, tag, or publisher" autocomplete="off"></label>'
			.implode('',$fields)
			.'<div class="dp-package-catalog-toggles" aria-label="Package availability">'.implode('',$toggles).'</div>'
			.'<input type="hidden" name="limit" value="'.self::e((string)$limit).'"><div class="dp-panel-actions"><button type="submit" class="dp-panel-button">Search catalog</button>'.($query!==''||array_filter($filters)?'<a class="dp-panel-button" href="'.self::e($base!==''?$base:'?').'">Clear</a>':'').'</div></form>';

		$registryMeta='<dl class="dp-package-catalog-meta">'
			.'<div><dt>Registry</dt><dd><code>'.self::e((string)($manifest['registry']??'')).'</code></dd></div>'
			.'<div><dt>Publication</dt><dd>'.(($manifest['published']??false)?'Sequence '.(int)($manifest['sequence']??0):'Awaiting first publication').'</dd></div>'
			.'<div><dt>Packages</dt><dd>'.(int)($manifest['package_count']??0).' packages / '.(int)($manifest['package_version_count']??0).' versions</dd></div>'
			.'<div><dt>Index</dt><dd>'.(is_string($manifest['index_digest']??null)?'<code>'.self::e(substr((string)$manifest['index_digest'],0,12)).'…</code>':'Not published').'</dd></div>'
			.'</dl>';

		$cards=[];
		foreach((array)($discovery['packages']??[])as$package){
			if(!is_array($package)){continue;}
			$listing=is_array($package['listing']??null)?$package['listing']:[];
			$id=(string)($package['id']??'');$version=(string)($package['version']??'');
			$availability=($package['revoked']??false)?'Revoked':(($package['publisher_blocked']??false)?'Publisher blocked':(($package['yanked']??false)?'Yanked':'Available'));
			$tone=$availability==='Available'?'success':'danger';
			$badges=[self::badge($availability,$tone)];
			foreach(['type','license']as$field){$value=(string)($listing[$field]??'');if($value!==''){$badges[]=self::badge($value,'neutral');}}
			$provides=[];foreach((array)($listing['provides']??[])as$value){if(is_string($value)&&$value!==''){$provides[]='<li><code>'.self::e($value).'</code></li>';}}
			$tags=[];foreach(array_merge((array)($listing['categories']??[]),(array)($listing['tags']??[]))as$value){if(is_string($value)&&$value!==''){$tags[]='<span>'.self::e(self::humanize($value)).'</span>';}}
			$links=[];foreach((array)($listing['links']??[])as$link){if(!is_array($link)){continue;}$target=self::url((string)($link['target']??''));if($target!==''){$links[]='<a href="'.self::e($target).'" rel="noopener noreferrer">'.self::e((string)($link['label']??'Package link')).'</a>';}}
			$artifact=is_array($package['artifact']??null)?$package['artifact']:[];
			$cards[]='<article class="dp-panel-card dp-package-card" data-dp-package="'.self::e($id).'" data-dp-package-version="'.self::e($version).'">'
				.'<header><div><strong>'.self::e((string)($listing['label']??self::humanize($id))).'</strong><small><code>'.self::e($id.'@'.$version).'</code></small></div><div class="dp-package-card-badges">'.implode('',$badges).'</div></header>'
				.'<p>'.self::e((string)($listing['description']??'No marketplace description supplied.')).'</p>'
				.($tags!==[]?'<div class="dp-package-card-tags" aria-label="Categories and tags">'.implode('',$tags).'</div>':'')
				.'<dl class="dp-package-card-details"><div><dt>Publisher</dt><dd>'.self::e((string)($package['publisher']??'Unknown')).'</dd></div><div><dt>Release</dt><dd>'.self::e(self::humanize((string)($package['status']??'unknown'))).'</dd></div><div><dt>Artifact</dt><dd>'.self::e(self::formatBytes((int)($artifact['bytes']??0))).'</dd></div><div><dt>Signing key</dt><dd><code>'.self::e((string)($package['key_id']??'Unknown')).'</code></dd></div></dl>'
				.($provides!==[]?'<div class="dp-package-card-provides"><span>Provides</span><ul>'.implode('',$provides).'</ul></div>':'')
				.($links!==[]?'<nav class="dp-package-card-links" aria-label="'.self::e((string)($listing['label']??$id)).' links">'.implode('',$links).'</nav>':'')
				.'</article>';
		}
		$count=(int)($discovery['total']??0);
		$meta=$count===1?'1 package':$count.' packages';
		$results='<section aria-labelledby="dp-packages-results">'.self::sectionHeading('dp-packages-results','Verified packages',$meta)
			.($cards!==[]?'<div class="dp-panel-collection dp-package-catalog-results" data-dp-display="brick">'.implode('',$cards).'</div>':self::empty(($manifest['published']??false)?'No packages match this catalog view.':'No registry publication yet.',($manifest['published']??false)?'Change the search or availability filters to broaden discovery.':'Commit a signed registry publication and verified packages will appear here.'));
		$next=$discovery['next_cursor']??null;
		if(is_string($next)&&$next!==''){
			$nextQuery=['q'=>$query,'limit'=>$limit,'cursor'=>$next];
			foreach($fieldLabels as$field=>$label){if(is_array($filters[$field]??null)&&$filters[$field]!==[]){$nextQuery[$field]=$filters[$field];}}
			foreach(['include_yanked','include_revoked','include_blocked','all_versions']as$name){if(($filters[$name]??false)===true){$nextQuery[$name]='1';}}
			$results.='<nav class="dp-package-catalog-pagination" aria-label="Package catalog pagination"><a class="dp-panel-button" href="'.self::e(self::queryUrl($base,$nextQuery)).'">Next packages</a></nav>';
		}
		$results.='</section>';
		$body='<section aria-labelledby="dp-packages-registry">'.self::sectionHeading('dp-packages-registry','Registry state',($manifest['published']??false)?'Signed index verified':'Unpublished').$registryMeta.$search.'</section>'.$results;
		return self::page('Package registry','Discover signed, policy-aware Panel extensions without exposing artifact locators or package bytes.',$body,['catalog'=>$manifest,'discovery'=>$discovery,'surface'=>'package_registry_catalog'],$options);
	}

	public static function developer(PanelManifestInspector $inspection, ?PanelManifestDiff $diff=null, ?PanelQualityMatrix $matrix=null, array $options=[]): PanelPageResult {
		$report=$inspection->jsonSerialize(); $body='<section aria-labelledby="dp-inspection-heading">'.self::sectionHeading('dp-inspection-heading','Manifest inspection',$inspection->passed()?'Passed':'Issues found').'<dl class="dp-panel-infolist"><div><dt>Hash</dt><dd><code>'.self::e($inspection->hash()).'</code></dd></div><div><dt>Nodes</dt><dd>'.self::e((string)$report['metrics']['nodes']).'</dd></div><div><dt>Maximum depth</dt><dd>'.self::e((string)$report['metrics']['maximum_depth']).'</dd></div></dl>'.self::issueList($report['issues']).'</section>';
		if($diff!==null){ $payload=$diff->jsonSerialize(); $body.='<section aria-labelledby="dp-diff-heading">'.self::sectionHeading('dp-diff-heading','Contract diff',$payload['summary']['total'].' changes').self::issueList(array_map(static fn(array $change): array => ['severity'=>'info','rule'=>$change['type'],'path'=>$change['path'],'message'=>self::scalar($change['before']).' → '.self::scalar($change['after'])], $payload['changes'])).'</section>'; }
		if($matrix!==null){ $payload=$matrix->jsonSerialize(); $body.='<section aria-labelledby="dp-quality-heading">'.self::sectionHeading('dp-quality-heading','Quality matrix',$payload['cases'].' browser cases').'<p>Keyboard, focus, contrast, zoom, direction, motion, network, locale, theme, and viewport plans are ready for execution.</p></section>'; }
		return self::page('Panel developer tools', 'Inspect contracts, generate resources, compare manifests, and execute quality matrices.', $body, ['inspection'=>$report, 'diff'=>$diff?->jsonSerialize(), 'quality'=>$matrix?->jsonSerialize(), 'surface'=>'developer_tools'], $options);
	}

	private static function opsStat(string $label,string $value,string $tone,string $detail):string{return'<div data-tone="'.self::e($tone).'"><dt>'.self::e($label).'</dt><dd>'.self::e($value).'</dd><small>'.self::e($detail).'</small></div>';}
	/** @param array<string,mixed> $input */
	private static function consoleCommandButton(string $url,string $tenant,string $command,string $ability,array $input,string $label,array $options=[]):string{
		$encoded=json_encode(PanelOperationsGuard::safeMetadata($input,64),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$risk=str_contains($command,'.policy.')?'critical':'high';$key='console:'.substr(hash('sha256',$tenant.'|'.$command.'|'.$encoded.'|'.bin2hex(random_bytes(12))),0,40);
		return self::postButton($url,'','operation','dispatch',$label,self::consoleFormFields($options,['command'=>$command,'ability'=>$ability,'tenant_id'=>$tenant,'idempotency_key'=>$key,'risk'=>$risk,'input'=>$encoded]));
	}
	/** @param array<string,mixed> $options @param array<string,mixed> $fields @return array<string,mixed> */
	private static function consoleFormFields(array $options,array $fields=[]):array{
		$name=trim((string)($options['csrf_name']??''));$token=$options['csrf_token']??null;
		if($name!==''&&is_scalar($token)&&preg_match('/^[A-Za-z_][A-Za-z0-9_.:-]{0,63}$/D',$name)===1){$fields[$name]=(string)$token;}
		return$fields;
	}
	private static function basisPoints(int $value):string{return number_format(max(0,min(10000,$value))/100,2,'.','').'%';}
	private static function page(string $title,string $description,string $body,array $data,array $options): PanelPageResult { $asset=self::url(PanelRenderer::assetUrl('panel-platform.css')); $html=($asset!==''?'<link rel="stylesheet" href="'.self::e($asset).'" data-dp-panel-platform-asset>':'').'<main class="dp-panel dp-panel-platform-page" data-dp-panel-kind="'.self::e((string)($data['surface']??'platform')).'"><header class="dp-panel-page-header"><div><p class="dp-panel-eyebrow">'.self::e((string)($options['eyebrow']??'DATAPHYRE PANEL')).'</p><h1>'.self::e($title).'</h1><p>'.self::e($description).'</p></div></header><div class="dp-panel-page-content">'.$body.'</div></main>'; return PanelPageResult::html($html,200,$data); }
	private static function sectionHeading(string $id,string $title,string $meta): string { return '<header class="dp-panel-section-header"><div><h2 id="'.self::e($id).'">'.self::e($title).'</h2><small>'.self::e($meta).'</small></div></header>'; }
	private static function empty(string $title,string $description): string { return '<div class="dp-panel-empty-state"><strong>'.self::e($title).'</strong><p>'.self::e($description).'</p></div>'; }
	private static function badge(string $label,string $tone): string { return '<span class="dp-panel-badge" data-tone="'.self::e($tone).'">'.self::e(self::humanize($label)).'</span>'; }
	private static function statusTone(string $status): string { $status=strtolower($status); return match(true){ in_array($status,['completed','committed','approved','ready','active','success','succeeded','passed','delivered','processed','rolled_back'],true)=>'success', in_array($status,['failed','rejected','denied','cancelled','error','attention','rollback_failed','blocked'],true)=>'danger', in_array($status,['running','processing','queued','pending','sending','draft','paused','retry_wait','awaiting_approval','dispatching'],true)=>'info', default=>'neutral' }; }
	private static function operationActions(array $record,array $options): string { $status=(string)($record['status']??''); $id=(string)($record['id']??''); $url=(string)($options['action_url']??''); $actions=[]; if($status==='running'){ $actions[]=self::postButton($url,$id,'operation','pause','Pause'); $actions[]=self::postButton($url,$id,'operation','cancel','Cancel'); } if($status==='paused'){ $actions[]=self::postButton($url,$id,'operation','resume','Resume'); } if(in_array($status,['failed','cancelled'],true)){ $actions[]=self::postButton($url,$id,'operation','retry','Retry'); } foreach($record['artifacts']??[] as $artifact){ if(is_array($artifact)&&isset($artifact['location'])){ $location=self::url((string)$artifact['location']);if($location!==''){$actions[]='<a class="dp-panel-button" href="'.self::e($location).'">'.self::e((string)($artifact['name']??'Artifact')).'</a>';} } } return implode('',$actions); }
	private static function postButton(string $url,string $id,string $name,string $value,string $label,array $hidden=[]): string { $fields='';foreach($hidden as$key=>$field){$fields.='<input type="hidden" name="'.self::e((string)$key).'" value="'.self::e((string)$field).'">';}return '<form method="post" action="'.self::e(self::url($url)).'" data-dp-panel-ajax>'.$fields.'<input type="hidden" name="id" value="'.self::e($id).'"><input type="hidden" name="'.self::e($name).'" value="'.self::e($value).'"><button type="submit" class="dp-panel-button">'.self::e($label).'</button></form>'; }
	private static function timeline(array $events): string { if($events===[]){return '';} $items=[]; foreach(array_slice($events,-20) as $event){ if(!is_array($event)){continue;} $items[]='<li><strong>'.self::e(self::humanize((string)($event['transition']??$event['type']??'Event'))).'</strong><time>'.self::e((string)($event['timestamp']??$event['at']??'')).'</time></li>'; } return '<ol class="dp-panel-timeline">'.implode('',$items).'</ol>'; }
	private static function issueList(array $issues): string { if($issues===[]){return self::empty('No issues detected.','The inspected contract satisfies the current gates.');} $items=[]; foreach($issues as $issue){ $items[]='<li data-severity="'.self::e((string)($issue['severity']??'info')).'"><strong>'.self::e((string)($issue['rule']??'issue')).'</strong><code>'.self::e((string)($issue['path']??'')).'</code><span>'.self::e((string)($issue['message']??'')).'</span></li>'; } return '<ul class="dp-panel-issue-list">'.implode('',$items).'</ul>'; }
	private static function humanize(string $value): string { return ucwords(str_replace(['_','-'], ' ', trim($value))); }
	/** @param array<string,string> $values */
	private static function options(array $values,string $selected):string { $html=[];foreach($values as$value=>$label){$html[]='<option value="'.self::e($value).'"'.($value===$selected?' selected':'').'>'.self::e($label).'</option>';}return implode('',$html); }
	private static function url(string $value):string { $value=trim($value);if($value===''||preg_match('/[\x00-\x1F\x7F]/',$value)===1||str_starts_with($value,'//')){return '';}if(preg_match('/^[a-z][a-z0-9+.-]*:/i',$value)===1&&preg_match('/^https?:/i',$value)!==1){return '';}return$value; }
	/** @param array<string,mixed> $query */
	private static function queryUrl(string $base,array $query):string {
		$query=array_filter($query,static fn(mixed$value):bool=>$value!==null&&$value!==''&&$value!==[]&&$value!==false);
		$encoded=http_build_query($query,'','&',PHP_QUERY_RFC3986);
		if($encoded===''){return$base!==''?$base:'?';}
		return($base!==''?$base:'').(str_contains($base,'?')?'&':'?').$encoded;
	}
	private static function formatBytes(int $bytes):string {
		if($bytes<1){return'Unknown';}
		$units=['B','KB','MB','GB'];$value=(float)$bytes;$unit=0;
		while($value>=1024&&$unit<count($units)-1){$value/=1024;$unit++;}
		return($unit===0?(string)$bytes:number_format($value,$value>=10?1:2,'.','')).' '.$units[$unit];
	}
	private static function scalar(mixed $value): string { return is_scalar($value)||$value===null ? var_export($value,true) : (json_encode($value,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?:''); }
	private static function e(string $value): string { return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
}
